      SetBgTilemapBuffer(1, sHofGfxPtr.tilemap1);
      SetBgTilemapBuffer(3, sHofGfxPtr.tilemap2);
      ChangeBgX(0, 0, BG_COORD_SET);
      ChangeBgY(0, 0, BG_COORD_SET);
      ChangeBgX(1, 0, BG_COORD_SET);
