/** static bool8 LoadHofBgs(void) */
export function LoadHofBgs(): any {
  switch (sHofGfxPtr.state)
      {
      case 0:
          DecompressAndCopyTileDataToVram(1, sHallOfFame_Gfx, 0, 0, 0);
          break;
      case 1:
          if (FreeTempTileDataBuffersIfPossible())
              return TRUE;
          break;
      case 2:
          FillBgTilemapBufferRect_Palette0(1, 1, 0, 0, 0x20, 2);
          FillBgTilemapBufferRect_Palette0(1, 0, 0, 3, 0x20, 0xB);
          FillBgTilemapBufferRect_Palette0(1, 1, 0, 0xE, 0x20, 6);
          FillBgTilemapBufferRect_Palette0(3, 2, 0, 0, 0x20, 0x20);

          CopyBgTilemapBufferToVram(1);
          CopyBgTilemapBufferToVram(3);
          break;
      case 3:
          InitStandardTextBoxWindows();
          InitTextBoxGfxAndPrinters();
          break;
      case 4:
          SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          ShowBg(0);
          ShowBg(1);
          ShowBg(3);
          sHofGfxPtr.state = 0;
          return FALSE;
      }

      sHofGfxPtr.state++;
      return TRUE;
}

/** static void SpriteCB_GetOnScreenAndAnimate(struct Sprite *sprite) */
export function SpriteCB_GetOnScreenAndAnimate(sprite: any): any {
  if (sprite.x != sprite.tDestinationX
          || sprite.y != sprite.tDestinationY)
      {
          if (sprite.x < sprite.tDestinationX)
              sprite.x += 15;
          if (sprite.x > sprite.tDestinationX)
              sprite.x -= 15;

          if (sprite.y < sprite.tDestinationY)
              sprite.y += 10;
          if (sprite.y > sprite.tDestinationY)
              sprite.y -= 10;
      }
      else
      {
          let species: any = sprite.tSpecies;

          if (species == (412))
              DoMonFrontSpriteAnimation(sprite, species, TRUE, 3);
          else
              DoMonFrontSpriteAnimation(sprite, species, FALSE, 3);
      }
}

/** static void SpriteCB_HofConfetti(struct Sprite *sprite) */
export function SpriteCB_HofConfetti(sprite: any): any {
  if (sprite.y2 > 120)
      {
          DestroySprite(sprite);
      }
      else
      {
          let rand: any = null;
          let sineIdx: any = null;

          sprite.y2++;
          sprite.y2 += sprite.sExtraY;

          sineIdx = sprite.sSineIdx;
          rand = (Random() % 4) + 8;
          sprite.x2 = rand * gSineTable[sineIdx] / 256;

          sprite.sSineIdx += 4;
      }
}

/** static bool8 CreateHofConfettiSprite(void) */
export function CreateHofConfettiSprite(): any {
  let spriteID: any = null;
      let sprite: any = null;

      let posX: any = Random() % DISPLAY_WIDTH;
      let posY: any = -(Random() % 8);

      spriteID = CreateSprite(sSpriteTemplate_HofConfetti, posX, posY, 0);
      sprite =gSprites[spriteID];

      StartSpriteAnim(sprite, Random() % ARRAY_COUNT(sAnims_Confetti));

       
      if (Random() & 3)
          sprite.sExtraY = 0;
      else
          sprite.sExtraY = 1;

      return FALSE;
}

/** void DoDomeConfetti(void) */
export function DoDomeConfetti(): any {
  let taskId: any = null;

      gSpecialVar_0x8004 = 180;
      taskId = CreateTask(Task_DoDomeConfetti, 0);
      if (taskId != ((0xFF)))
      {
          gTasks[taskId].tTimer = gSpecialVar_0x8004;
          gSpecialVar_0x8005 = taskId;
      }
}

/** static void StopDomeConfetti(void) */
export function StopDomeConfetti(): any {
  let taskId: any = null;

      if ((taskId = FindTaskIdByFunc(Task_DoDomeConfetti)) != ((0xFF)))
          DestroyTask(taskId);

      ConfettiUtil_Free();
      FreeSpriteTilesByTag((1001));
      FreeSpritePaletteByTag((1001));
}

/** static void UpdateDomeConfetti(struct ConfettiUtil *util) */
export function UpdateDomeConfetti(util: any): any {
  if (util.yDelta > 110)
      {
           
          gTasks[util.data[(7)]].tConfettiCount--;
          ConfettiUtil_Remove(util.id);
      }
      else
      {
           
          let sineIdx: any = null;
          let rand: any = null;

          util.yDelta++;
          util.yDelta += util.data[(1)];

          sineIdx = util.data[(0)];
          rand = Random();
          rand &= 3;
          rand += 8;
          util.xDelta = (rand) * ((gSineTable[sineIdx])) / 256;

          util.data[(0)] += 4;
      }
}

/** static void Task_DoDomeConfetti(u8 taskId) */
export function Task_DoDomeConfetti(taskId: any): any {
  let id: any = 0;
      let data: any = gTasks[taskId].data;

      switch (tState)
      {
      case 0:
          if (!ConfettiUtil_Init(64))
          {
               
              DestroyTask(taskId);
              gSpecialVar_0x8004 = 0;
              gSpecialVar_0x8005 = 0xFFFF;
          }
          LoadCompressedSpriteSheet(sSpriteSheet_Confetti);
          LoadCompressedSpritePalette(sSpritePalette_Confetti);
          tState++;
          break;
      case 1:
          if (tTimer != 0 && tTimer % 3 == 0)
          {
               
              id = ConfettiUtil_AddNew(sOamData_Confetti,
                                (1001),
                                (1001),
                                Random() % DISPLAY_WIDTH,
                                -(Random() % 8),
                                Random() % ARRAY_COUNT(sAnims_Confetti),
                                id);
              if (id != 0xFF)
              {
                  ConfettiUtil_SetCallback(id, UpdateDomeConfetti);

                   
                  if ((Random() % 4) == 0)
                      ConfettiUtil_SetData(id, (1), 1);

                  ConfettiUtil_SetData(id, (7), taskId);
                  tConfettiCount++;
              }
          }

          ConfettiUtil_Update();
          if (tTimer != 0)
              tTimer--;
          else if (tConfettiCount == 0)
              tState = 0xFF;
          break;
      case 0xFF:
          StopDomeConfetti();
          gSpecialVar_0x8004 = 0;
          gSpecialVar_0x8005 = 0xFFFF;
          break;
      }
}

